import { defineTheme } from "@cueplusplus/theme-tools";

/**
 * The RequestPort palette, generated by the CUE++ theme tools from the two
 * DTCG sources beside this file.
 *
 * `complete`, not the default `delta`: every one of the 26 contract colours is
 * stated here rather than inherited, so the stylesheet this emits stands on its
 * own over the blank base `@cueplusplus/ui/styles.css` paints.
 *
 * `package` names this workspace rather than `@cueplusplus/theme-requestport`,
 * because the palette is RequestPort's. The generated `index.d.ts` still
 * augments `@cueplusplus/theme-base`'s registry, so `ThemeName` closes over
 * "requestport" exactly as it did when the theme arrived from the registry.
 */
export default defineTheme({
  name: "requestport",
  package: "@requestport/theme",
  mode: "complete",
  sources: {
    dark: "src/requestport.dark.tokens.json",
    light: "src/requestport.light.tokens.json",
  },
});
